/**
 *
 * @param value
 */
function escapeSheetText(value) {
  return String(value === undefined || value === null ? "" : value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

/**
 *
 * @param index
 */
function getColumnName(index) {
  let columnName = "";
  let current = index;
  while (current > 0) {
    const remainder = (current - 1) % 26;
    columnName = String.fromCharCode(65 + remainder) + columnName;
    current = Math.floor((current - 1) / 26);
  }
  return columnName;
}

/**
 *
 * @param rows
 */
function createSheetXml(rows) {
  const sheetRows = rows
    .map((row, rowIndex) => {
      const cells = row
        .map((value, columnIndex) => {
          const cellReference = `${getColumnName(columnIndex + 1)}${rowIndex + 1}`;
          return `<c r="${cellReference}" t="inlineStr"><is><t>${escapeSheetText(value)}</t></is></c>`;
        })
        .join("");
      return `<row r="${rowIndex + 1}">${cells}</row>`;
    })
    .join("");
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${sheetRows}</sheetData></worksheet>`;
}

/**
 *
 * @param value
 * @param fallback
 */
function normalizeQueryList(value, fallback) {
  if (!value) {
    return fallback;
  }
  const list = Array.isArray(value) ? value : String(value).split(",");
  const cleanList = list.map((item) => String(item).trim()).filter(Boolean);
  return cleanList.length > 0 ? cleanList : fallback;
}

/**
 *
 * @param value
 * @param suffix
 */
function safeSheetName(value, suffix = "") {
  const cleanName = String(value || "学科")
    .replaceAll(/[*/:?[\\\]]/g, "")
    .slice(0, 31 - suffix.length);
  return `${cleanName || "学科"}${suffix}`;
}

/**
 *
 * @param value
 * @param fallback
 */
function cleanDownloadFilePart(value, fallback) {
  const text = String(value || "")
    .trim()
    .replaceAll(/\s+/g, "");
  const cleanText = text.replaceAll(/["*/:<>?[\\\]|]/g, "").slice(0, 80);
  return cleanText || fallback;
}

/**
 *
 * @param options
 */
function getScoreImportTemplateFileName(options = {}) {
  const examName = cleanDownloadFilePart(options.examName, "成绩导入");
  const examTime = cleanDownloadFilePart(
    options.examTime || options.examDate,
    "",
  );
  const suffix = options.importMode === "append" ? "_原始成绩" : "";
  return `${examName}${examTime ? `_${examTime}` : ""}${suffix}.xlsx`;
}

