/**
 *
 * @param value
 */
function parseJsonList(value) {
  if (!value) {
    return [];
  }
  if (Array.isArray(value)) {
    return value;
  }
  try {
    const result = JSON.parse(value);
    return Array.isArray(result) ? result : [];
  } catch {
    return [];
  }
}

/**
 *
 * @param options
 */
function normalizeSubjectConfigs(options = {}) {
  const parsedConfigs = parseJsonList(
    options.subjectConfigListString || options.subjectConfigList,
  );
  if (parsedConfigs.length > 0) {
    return parsedConfigs.map((item, index) => ({
      subjectId: item.subjectId || item.key || item.value || String(index + 1),
      subjectName:
        item.subjectName || item.label || item.name || `学科${index + 1}`,
      courseIdList: item.courseIdList || [],
      courseNameList: item.courseNameList || [],
      groupIdList: item.groupIdList || [],
      groupNameList: item.groupNameList || [],
      fullScore: item.fullScore ?? item.totalScore ?? "",
    }));
  }
  const subjectIds = normalizeQueryList(
    options.subjectIdListString || options.subjectIdList,
    [],
  );
  const fallback =
    subjectIds.length > 0
      ? subjectIds.map((subjectId, index) => `学科${index + 1}`)
      : ["物理"];
  const subjectNames = normalizeQueryList(
    options.subjectNameListString,
    fallback,
  );
  return subjectNames.map((subjectName, index) => ({
    subjectId: subjectIds[index] || String(index + 1),
    subjectName,
    courseIdList: [],
    courseNameList: [],
    groupIdList: [],
    groupNameList: [],
    fullScore: "",
  }));
}

/**
 *
 * @param groupIds
 * @param groupNames
 */
function uniqueGroups(groupIds, groupNames) {
  const groupMap = new Map();
  const groupCount = Math.max(groupIds.length, groupNames.length);
  for (let index = 0; index < groupCount; index += 1) {
    const groupId = groupIds[index] || String(100 + index);
    const key = String(groupId);
    if (!groupMap.has(key)) {
      groupMap.set(key, {
        groupId,
        groupName: groupNames[index] || `八年级${index + 1}班`,
      });
    }
  }
  return [...groupMap.values()];
}

/**
 *
 * @param options
 * @param subjectConfig
 */
function buildTemplateGroups(options = {}, subjectConfig) {
  if (
    subjectConfig?.groupIdList?.length ||
    subjectConfig?.groupNameList?.length
  ) {
    return uniqueGroups(
      subjectConfig.groupIdList || [],
      subjectConfig.groupNameList || [],
    );
  }
  const groupIds = normalizeQueryList(
    options.groupIdListString || options.groupIdList,
    [],
  );
  const groupNames = normalizeQueryList(options.groupNameListString, []);
  if (groupIds.length > 0 || groupNames.length > 0) {
    return uniqueGroups(groupIds, groupNames);
  }
  const subjectConfigs = normalizeSubjectConfigs(options);
  const rowGroupIds = [];
  const rowGroupNames = [];
  for (const item of subjectConfigs) {
    for (const [index, groupId] of (item.groupIdList || []).entries()) {
      rowGroupIds.push(groupId);
      rowGroupNames.push(item.groupNameList?.[index] || "");
    }
  }
  if (rowGroupIds.length > 0 || rowGroupNames.length > 0) {
    return uniqueGroups(rowGroupIds, rowGroupNames);
  }
  return uniqueGroups(["101", "102"], ["三一班", "三二班"]);
}

/**
 *
 * @param groupId
 * @param groupIndex
 */
function getGroupCode(groupId, groupIndex) {
  const digits = String(groupId || "").replaceAll(/\D/g, "");
  return (digits || String(groupIndex + 1)).slice(-2).padStart(2, "0");
}

