/**
 *
 * @param value
 */
function normalizeChoiceAnswer(value) {
  const normalized = String(value || "")
    .trim()
    .replaceAll(/[\s,/;|，；]+/g, "")
    .toUpperCase();
  if (!normalized || !/^[A-Z]+$/.test(normalized)) {
    return normalized;
  }
  return [...new Set(normalized.split(""))].sort().join("");
}

/**
 *
 * @param questionType
 */
function isChoiceQuestionType(questionType) {
  return ["单选", "多选", "选择题"].some((type) =>
    String(questionType || "").includes(type),
  );
}

/**
 *
 * @param question
 * @param rawValue
 */
function calculateMockQuestionScore(question, rawValue) {
  const fullScore = Number(question.fullScore);
  const rawText = String(
    rawValue === undefined || rawValue === null ? "" : rawValue,
  ).trim();
  if (!rawText) {
    return {
      score: null,
      status: "空值",
    };
  }
  if (["缺考", "缺", "未扫", "不计排名"].includes(rawText)) {
    return {
      score: null,
      status: rawText,
    };
  }
  if (isChoiceQuestionType(question.questionType)) {
    const answer = normalizeChoiceAnswer(rawText);
    const correct = normalizeChoiceAnswer(question.correctAnswer);
    const score = Number(rawText);
    if (Number.isFinite(score)) {
      if (score < 0) {
        return {
          score,
          status: "得分小于0",
        };
      }
      if (score > fullScore) {
        return {
          score,
          status: "得分超满分",
        };
      }
      return {
        score,
        status: "可导入",
      };
    }
    if (!correct) {
      return {
        score: null,
        status: "缺少正确答案",
      };
    }
    if (!/^[A-Z]+$/.test(answer)) {
      return {
        score: null,
        status: "选择题答案非法",
      };
    }
    if (String(question.questionType).includes("单选") && answer.length > 1) {
      return {
        score: null,
        status: "单选题只能填写一个选项",
      };
    }
    return {
      score: answer === correct ? fullScore : 0,
      status: "可导入",
    };
  }
  const score = Number(rawText);
  if (!Number.isFinite(score)) {
    return {
      score: null,
      status: "得分不是数字",
    };
  }
  if (score < 0) {
    return {
      score,
      status: "得分小于0",
    };
  }
  if (score > fullScore) {
    return {
      score,
      status: "得分超满分",
    };
  }
  return {
    score,
    status: "可导入",
  };
}

/**
 *
 * @param studentIndex
 * @param questionIndex
 */
function getMockRawQuestionValue(studentIndex, questionIndex) {
  const question = mockQuestionTemplate[questionIndex];
  if (!question) {
    return "";
  }
  if (isChoiceQuestionType(question.questionType)) {
    return (studentIndex + questionIndex) % 5 === 0
      ? "0"
      : question.correctAnswer;
  }
  const fullScore = Number(question.fullScore) || 0;
  const deduction = (studentIndex + questionIndex) % 4;
  return String(Math.max(0, fullScore - deduction));
}

/**
 *
 * @param isAppend
 * @param studentIndex
 * @param subjectIndex
 * @param questionIndex
 */
function getDownloadedQuestionValue(
  isAppend,
  studentIndex,
  subjectIndex,
  questionIndex,
) {
  if (!isAppend) {
    return "";
  }
  // 批量订正下载的是当前考试已有成绩，本地 mock 用稳定规则预填，方便直接改原成绩再上传。
  return getMockRawQuestionValue(studentIndex + subjectIndex, questionIndex);
}

/**
 *
 * @param isAppend
 * @param studentIndex
 * @param subjectIndex
 */
function getDownloadedSubjectScore(isAppend, studentIndex, subjectIndex) {
  if (!isAppend) {
    return "";
  }
  const totalScore = mockQuestionTemplate.reduce(
    (total, question, questionIndex) => {
      const rawValue = getDownloadedQuestionValue(
        isAppend,
        studentIndex,
        subjectIndex,
        questionIndex,
      );
      const scoreResult = calculateMockQuestionScore(question, rawValue);
      const score = Number(scoreResult.score);
      return scoreResult.status === "可导入" && Number.isFinite(score)
        ? total + score
        : total;
    },
    0,
  );
  return String(totalScore);
}

/**
 *
 * @param row
 */
function getPreviewStudentKey(row) {
  return [row.studentNo, row.studentName, row.className].join("|");
}

/**
 *
 * @param row
 */
function getStudentSubjectKey(row) {
  return [getPreviewStudentKey(row), row.subjectName || ""].join("|");
}

/**
 *
 * @param value
 */
function isMockAbsentValue(value) {
  return ["缺考", "缺", "未扫", "不计排名"].includes(
    String(value || "").trim(),
  );
}

/**
 *
 * @param row
 */
function isNoAnswerQuestionRow(row) {
  const rawText = String(row.rawValue ?? "").trim();
  const score = Number(row.score);
  return (
    row.status === "空值" ||
    isMockAbsentValue(row.status) ||
    isMockAbsentValue(rawText) ||
    rawText === "" ||
    score === 0
  );
}

/**
 *
 * @param row
 */
function isBlankOrAbsentQuestionRow(row) {
  const rawText = String(row.rawValue ?? "").trim();
  return (
    row.status === "空值" ||
    isMockAbsentValue(row.status) ||
    isMockAbsentValue(rawText) ||
    rawText === ""
  );
}

/**
 *
 * @param questionScoreRows
 * @param subjectScoreRows
 */
function normalizeQuestionAbsentStatus(
  questionScoreRows,
  subjectScoreRows = [],
) {
  const subjectScoreMap = new Map();
  for (const row of subjectScoreRows) {
    const score = Number(row.score);
    subjectScoreMap.set(
      getStudentSubjectKey(row),
      Number.isFinite(score) ? score : null,
    );
  }

  const questionGroupMap = new Map();
  for (const row of questionScoreRows) {
    const key = getStudentSubjectKey(row);
    const rows = questionGroupMap.get(key) || [];
    rows.push(row);
    questionGroupMap.set(key, rows);
  }

  for (const [key, rows] of questionGroupMap.entries()) {
    const subjectScore = subjectScoreMap.get(key);
    const hasSubjectScore = subjectScoreMap.has(key) && subjectScore !== null;
    const hasPositiveSubjectScore = hasSubjectScore && subjectScore > 0;
    const shouldMarkAbsent =
      rows.length > 0 &&
      rows.every(isNoAnswerQuestionRow) &&
      !hasPositiveSubjectScore &&
      (!hasSubjectScore || subjectScore === 0);

    for (const row of rows) {
      if (shouldMarkAbsent && isNoAnswerQuestionRow(row)) {
        row.status = "缺考";
        row.score = null;
        continue;
      }
      if (!shouldMarkAbsent && isBlankOrAbsentQuestionRow(row)) {
        row.status = "空值";
        row.score = null;
      }
    }
  }

  return questionScoreRows;
}

/**
 *
 * @param subjectScoreRows
 * @param questionScoreRows
 */
function createScoreWorkbookRows(subjectScoreRows, questionScoreRows) {
  const rowMap = new Map();
  const ensureRow = (sourceRow, scoreSource) => {
    const key = getPreviewStudentKey(sourceRow);
    const current = rowMap.get(key) || {
      status: "可导入",
      studentNo: sourceRow.studentNo,
      studentName: sourceRow.studentName,
      className: sourceRow.className,
      totalScore: 0,
      fullScore: 0,
      scoreSource,
      subjectScoreMap: {},
      subjectFullScoreMap: {},
    };
    rowMap.set(key, current);
    return current;
  };

  for (const row of subjectScoreRows) {
    const score = Number(row.score);
    if (!row.subjectName || !Number.isFinite(score)) {
      continue;
    }
    const workbookRow = ensureRow(row, "1_学科得分");
    workbookRow.subjectScoreMap[row.subjectName] = score;
    workbookRow.subjectFullScoreMap[row.subjectName] =
      Number(row.fullScore) || 0;
    workbookRow.totalScore += score;
    workbookRow.fullScore += Number(row.fullScore) || 0;
  }

  if (rowMap.size > 0) {
    return [...rowMap.values()];
  }

  for (const row of questionScoreRows) {
    const score = Number(row.score);
    if (
      row.status !== "可导入" ||
      !row.subjectName ||
      !Number.isFinite(score)
    ) {
      continue;
    }
    const workbookRow = ensureRow(row, "小题得分汇总");
    workbookRow.subjectScoreMap[row.subjectName] =
      (workbookRow.subjectScoreMap[row.subjectName] || 0) + score;
    workbookRow.subjectFullScoreMap[row.subjectName] =
      (workbookRow.subjectFullScoreMap[row.subjectName] || 0) +
      (Number(row.fullScore) || 0);
    workbookRow.totalScore += score;
    workbookRow.fullScore += Number(row.fullScore) || 0;
  }
  return [...rowMap.values()];
}

/**
 *
 * @param questionScoreRows
 */
function createQuestionWorkbookList(questionScoreRows) {
  const groupMap = new Map();
  for (const row of questionScoreRows) {
    const subjectName = row.subjectName || "未识别学科";
    if (!groupMap.has(subjectName)) {
      groupMap.set(subjectName, {
        subjectName,
        sheetName: `${subjectName}_小题得分`,
        rows: [],
      });
    }
    groupMap.get(subjectName).rows.push(row);
  }
  return [...groupMap.values()];
}

const BLOCKING_STATUS_MESSAGE_MAP = {
  缺少满分: "题目缺少满分，请补齐满分行后重新上传",
  选择题答案非法: "选择题答案只能填写 A-Z 选项",
  单选题只能填写一个选项: "单选题只能填写一个选项",
  得分不是数字: "非选择题必须填写数字得分",
  得分小于0: "得分不能小于 0",
  得分超满分: "得分不能超过该题满分",
  缺少正确答案: "选择题缺少正确答案，无法按作答自动计分；请填写得分",
};

const WARNING_STATUS_MESSAGE_MAP = {
  空值: "当前单元格为空，将作为未录入处理",
  缺考: "识别为缺考，不会按 0 分自动写入",
  缺: "识别为缺考，不会按 0 分自动写入",
  未扫: "识别为未扫，需要老师确认是否补录",
  不计排名: "识别为不计排名，不参与排名类计算",
};

/**
 *
 * @param row
 */
function getQuestionIssuePosition(row) {
  return `${row.subjectName || "未知学科"}_小题得分 / ${
    row.className || "-"
  } / ${row.studentName || row.studentNo || "-"} / 第${
    row.questionNo || "-"
  }题`;
}

/**
 *
 * @param questionScoreRows
 * @param subjectScoreRows
 */
function createPreviewIssues(questionScoreRows, subjectScoreRows = []) {
  const errors = [];
  const warnings = [];
  for (const row of questionScoreRows) {
    if (BLOCKING_STATUS_MESSAGE_MAP[row.status]) {
      errors.push({
        position: getQuestionIssuePosition(row),
        message: `${BLOCKING_STATUS_MESSAGE_MAP[row.status]}（录入值：${
          row.rawValue ?? ""
        }，满分：${row.fullScore ?? ""}）`,
      });
      continue;
    }
    if (WARNING_STATUS_MESSAGE_MAP[row.status]) {
      warnings.push({
        position: getQuestionIssuePosition(row),
        message: WARNING_STATUS_MESSAGE_MAP[row.status],
      });
    }
  }

  const questionScoreMap = new Map();
  for (const row of questionScoreRows) {
    const score = Number(row.score);
    if (row.status !== "可导入" || !Number.isFinite(score)) {
      continue;
    }
    const key = [
      row.studentNo,
      row.studentName,
      row.className,
      row.subjectName,
    ].join("|");
    questionScoreMap.set(key, (questionScoreMap.get(key) || 0) + score);
  }

  for (const row of subjectScoreRows) {
    const subjectScore = Number(row.score);
    const key = [
      row.studentNo,
      row.studentName,
      row.className,
      row.subjectName,
    ].join("|");
    const questionScore = questionScoreMap.get(key);
    if (
      questionScore === undefined ||
      !Number.isFinite(subjectScore) ||
      Math.abs(subjectScore - questionScore) <= 0.01
    ) {
      continue;
    }
    warnings.push({
      position: `1_学科得分 / ${row.className || "-"} / ${
        row.studentName || row.studentNo || "-"
      } / ${row.subjectName || "-"}`,
      message: `学科分 ${subjectScore} 与小题汇总 ${questionScore} 不一致，导入前请确认以哪一份为准`,
    });
  }

  return { errors, warnings };
}

/**
 *
 * @param options
 */
function getScoreImportMockVariant(options = {}) {
  const fileName = String(options.fileName || options.fileId || "");
  if (/全错误|垃圾/.test(fileName)) {
    return "error";
  }
  if (/全警告|警告/.test(fileName)) {
    return "warning";
  }
  if (/完美/.test(fileName)) {
    return "perfect";
  }
  return "";
}

/**
 *
 * @param options
 */
function getFixtureSubjectConfigs(options = {}) {
  const subjectConfigs = normalizeSubjectConfigs(options);
  const baseConfig = subjectConfigs[0] || {};
  return ["语文", "数学", "英语"].map((subjectName, index) => ({
    subjectId: baseConfig.subjectId
      ? `${baseConfig.subjectId}-${index + 1}`
      : String(index + 1),
    subjectName,
    courseIdList: baseConfig.courseIdList || [],
    courseNameList: baseConfig.courseNameList || [],
    groupIdList: baseConfig.groupIdList || [],
    groupNameList: baseConfig.groupNameList || [],
    fullScore: 150,
  }));
}

/**
 *
 * @param variant
 * @param subjectName
 * @param question
 */
function getFixtureCorrectAnswer(variant, subjectName, question) {
  if (
    ((variant === "perfect" && subjectName === "英语") ||
      variant === "error") &&
    question.questionNo === "8"
  ) {
    return "";
  }
  return question.correctAnswer;
}

/**
 *
 * @param answer
 */
function getNextChoiceAnswer(answer) {
  const answerList = ["A", "B", "C", "D"];
  const normalizedAnswer = normalizeChoiceAnswer(answer);
  if (normalizedAnswer.length > 1) {
    return normalizedAnswer.includes("D") ? "AC" : `${normalizedAnswer}D`;
  }
  const index = answerList.indexOf(normalizedAnswer);
  return answerList[(index + 1) % answerList.length] || "A";
}

/**
 *
 * @param variant
 * @param subjectIndex
 * @param subjectName
 * @param studentIndex
 * @param question
 * @param questionIndex
 */
function getFixtureQuestionValue(
  variant,
  subjectIndex,
  subjectName,
  studentIndex,
  question,
  questionIndex,
) {
  if (variant === "error") {
    if (question.questionNo === "19") {
      return "1";
    }
    if (isChoiceQuestionType(question.questionType)) {
      return question.questionNo === "8"
        ? "A"
        : (studentIndex + questionIndex) % 2 === 0
          ? "A1"
          : "AB";
    }
    const errorValues = [
      "不是分数",
      "-1",
      String(Number(question.fullScore) + 6),
    ];
    return errorValues[(studentIndex + questionIndex) % errorValues.length];
  }

  if (variant === "warning") {
    if (studentIndex === 0 && subjectIndex === 0) {
      const noAnswerValues = ["", "缺考", "缺", "未扫", "0"];
      return noAnswerValues[questionIndex % noAnswerValues.length];
    }
    const warningValues = ["", "缺考", "缺", "未扫", "不计排名"];
    if ((studentIndex + questionIndex + subjectIndex) % 5 === 0) {
      return warningValues[
        (studentIndex + questionIndex) % warningValues.length
      ];
    }
  }

  if (isChoiceQuestionType(question.questionType)) {
    const correctAnswer = getFixtureCorrectAnswer(
      variant,
      subjectName,
      question,
    );
    if (!correctAnswer) {
      return String(Number(question.fullScore) - (studentIndex % 2));
    }
    return (studentIndex + questionIndex + subjectIndex) % 7 === 0
      ? getNextChoiceAnswer(correctAnswer)
      : correctAnswer;
  }

  if (variant === "perfect") {
    return question.fullScore;
  }
  return String(
    Math.max(
      0,
      Number(question.fullScore) - ((studentIndex + questionIndex) % 2),
    ),
  );
}

/**
 *
 * @param options
 */
function createStandardPreview(options = {}) {
  const mockVariant = getScoreImportMockVariant(options);
  const subjectConfigs = mockVariant
    ? getFixtureSubjectConfigs(options)
    : normalizeSubjectConfigs(options);
  const students = buildMockStudents(buildTemplateGroups(options));
  const questionScoreRows = subjectConfigs.flatMap(
    (subjectConfig, subjectIndex) => {
      const subjectStudents = buildMockStudents(
        buildTemplateGroups(options, subjectConfig),
      );
      return subjectStudents.flatMap((student, studentIndex) =>
        mockQuestionTemplate.map((question, questionIndex) => {
          const fixtureCorrectAnswer = getFixtureCorrectAnswer(
            mockVariant,
            subjectConfig.subjectName,
            question,
          );
          const fullScore =
            mockVariant === "error" && question.questionNo === "19"
              ? ""
              : question.fullScore;
          const rawValue = mockVariant
            ? getFixtureQuestionValue(
                mockVariant,
                subjectIndex,
                subjectConfig.subjectName,
                studentIndex,
                question,
                questionIndex,
              )
            : getMockRawQuestionValue(studentIndex, questionIndex);
          const scoreResult = calculateMockQuestionScore(
            {
              ...question,
              correctAnswer: fixtureCorrectAnswer,
              fullScore,
            },
            rawValue,
          );
          return {
            status: scoreResult.status,
            studentNo: student.studentNo,
            studentName: student.studentName,
            className: student.className,
            subjectName: subjectConfig.subjectName,
            courseName: (subjectConfig.courseNameList || []).join(","),
            moduleNo: question.moduleNo,
            subQuestionNo: question.subQuestionNo,
            questionNo: question.questionNo,
            questionType: question.questionType,
            rawValue,
            correctAnswer: fixtureCorrectAnswer,
            score: scoreResult.score,
            fullScore,
          };
        }),
      );
    },
  );
  const subjectScoreMap = new Map();
  for (const row of questionScoreRows) {
    const score = Number(row.score);
    if (row.status !== "可导入" || !Number.isFinite(score)) {
      continue;
    }
    const key = getStudentSubjectKey(row);
    subjectScoreMap.set(key, (subjectScoreMap.get(key) || 0) + score);
  }
  const subjectScoreRows = students.flatMap((student) =>
    subjectConfigs.map((subjectConfig) => {
      const key = getStudentSubjectKey({
        ...student,
        subjectName: subjectConfig.subjectName,
      });
      let score = subjectScoreMap.get(key) || 0;
      if (mockVariant === "warning") {
        if (
          student.studentNo === students[0]?.studentNo &&
          subjectConfig.subjectName === "语文"
        ) {
          score = 0;
        } else if (
          (students.indexOf(student) + subjectConfigs.indexOf(subjectConfig)) %
            2 ===
          1
        ) {
          score = Math.max(0, score - 2);
        }
      }
      if (mockVariant === "error") {
        score = "错误分";
      }
      return {
        status: "可导入",
        studentNo: student.studentNo,
        studentName: student.studentName,
        className: student.className,
        subjectName: subjectConfig.subjectName,
        courseName: (subjectConfig.courseNameList || []).join(","),
        fullScore: subjectConfig.fullScore || 150,
        questionNo: "学科分",
        moduleNo: "",
        subQuestionNo: "",
        questionType: "",
        rawValue: score,
        score,
      };
    }),
  );
  normalizeQuestionAbsentStatus(questionScoreRows, subjectScoreRows);
  const scoreWorkbookRows = createScoreWorkbookRows(
    subjectScoreRows,
    questionScoreRows,
  );
  const questionWorkbookList = createQuestionWorkbookList(questionScoreRows);
  const previewIssues = createPreviewIssues(
    questionScoreRows,
    subjectScoreRows,
  );
  const warnings = previewIssues.warnings;
  const isAppend = options.importMode === "append";
  return {
    previewId: "standard-preview-001",
    summary: {
      studentCount: students.length,
      subjectScoreCount: subjectScoreRows.length,
      scoreWorkbookRowCount: scoreWorkbookRows.length,
      questionWorkbookCount: questionWorkbookList.length,
      questionScoreCount: questionScoreRows.length,
      errorCount: previewIssues.errors.length,
      warningCount: warnings.length,
      importableCount:
        subjectScoreRows.length +
        questionScoreRows.filter((row) => row.status === "可导入").length,
    },
    scoreWorkbookRows,
    questionWorkbookList,
    subjectScoreRows,
    questionScoreRows,
    changeSummary: isAppend
      ? {
          addedStudentCount: 1,
          updatedStudentCount: Math.max(students.length - 1, 0),
          deletedStudentCount: 0,
          changedStudentCount: students.length,
        }
      : undefined,
    errors: previewIssues.errors,
    warnings,
  };
}

/**
 *
 * @param options
 */
function createZhixuePreview(options = {}) {
  const subjectConfig = normalizeSubjectConfigs(options)[0] || {};
  const subjectName = subjectConfig.subjectName || "物理";
  const students = buildMockStudents(
    buildTemplateGroups(options, subjectConfig),
  );
  const questionScoreRows = students.flatMap((student, studentIndex) =>
    mockQuestionTemplate.map((question, questionIndex) => {
      const rawValue = getMockRawQuestionValue(studentIndex + 1, questionIndex);
      const scoreResult = calculateMockQuestionScore(question, rawValue);
      return {
        status: scoreResult.status,
        studentNo: student.studentNo,
        studentName: student.studentName,
        className: student.className,
        subjectName,
        courseName: (subjectConfig.courseNameList || []).join(","),
        moduleNo: question.moduleNo,
        subQuestionNo: question.subQuestionNo,
        questionNo: question.questionNo,
        questionType: question.questionType,
        rawValue,
        correctAnswer: question.correctAnswer,
        score: scoreResult.score,
        fullScore: question.fullScore,
      };
    }),
  );
  normalizeQuestionAbsentStatus(questionScoreRows, []);
  const scoreWorkbookRows = createScoreWorkbookRows([], questionScoreRows);
  const questionWorkbookList = createQuestionWorkbookList(questionScoreRows);
  const previewIssues = createPreviewIssues(questionScoreRows);
  const warnings = [
    ...previewIssues.warnings,
    {
      position: `${subjectName} 题目列`,
      message: "识别到父题与子题共存时，只导入叶子题，父题汇总不计分",
    },
    {
      position: `${subjectName} 满分行`,
      message: "如果智学网文件缺少满分，生产解析服务会以最高得分推断并要求确认",
    },
  ];
  return {
    previewId: "zhixue-preview-001",
    summary: {
      studentCount: students.length,
      subjectScoreCount: 0,
      scoreWorkbookRowCount: scoreWorkbookRows.length,
      questionWorkbookCount: questionWorkbookList.length,
      questionScoreCount: questionScoreRows.length,
      errorCount: previewIssues.errors.length,
      warningCount: warnings.length,
      importableCount: questionScoreRows.filter(
        (row) => row.status === "可导入",
      ).length,
    },
    scoreWorkbookRows,
    questionWorkbookList,
    subjectScoreRows: [],
    questionScoreRows,
    errors: previewIssues.errors,
    warnings,
  };
}

