/**
 *
 */
function createCrc32Table() {
  const table = [];
  for (let index = 0; index < 256; index += 1) {
    let value = index;
    for (let index_ = 0; index_ < 8; index_ += 1) {
      value = value & 1 ? 0xed_b8_83_20 ^ (value >>> 1) : value >>> 1;
    }
    table[index] = value >>> 0;
  }
  return table;
}

const crc32Table = createCrc32Table();

/**
 *
 * @param buffer
 */
function getCrc32(buffer) {
  let crc = 0xff_ff_ff_ff;
  for (const element of buffer) {
    crc = crc32Table[(crc ^ element) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xff_ff_ff_ff) >>> 0;
}

/**
 *
 * @param fileMap
 */
function createZipBuffer(fileMap) {
  const localParts = [];
  const centralParts = [];
  let offset = 0;
  for (const fileName of Object.keys(fileMap)) {
    const nameBuffer = Buffer.from(fileName);
    const dataBuffer = Buffer.from(fileMap[fileName]);
    const crc = getCrc32(dataBuffer);
    const localHeader = Buffer.alloc(30);
    localHeader.writeUInt32LE(0x04_03_4b_50, 0);
    localHeader.writeUInt16LE(20, 4);
    localHeader.writeUInt16LE(0, 6);
    localHeader.writeUInt16LE(0, 8);
    localHeader.writeUInt16LE(0, 10);
    localHeader.writeUInt16LE(0, 12);
    localHeader.writeUInt32LE(crc, 14);
    localHeader.writeUInt32LE(dataBuffer.length, 18);
    localHeader.writeUInt32LE(dataBuffer.length, 22);
    localHeader.writeUInt16LE(nameBuffer.length, 26);
    localHeader.writeUInt16LE(0, 28);
    localParts.push(localHeader, nameBuffer, dataBuffer);

    const centralHeader = Buffer.alloc(46);
    centralHeader.writeUInt32LE(0x02_01_4b_50, 0);
    centralHeader.writeUInt16LE(20, 4);
    centralHeader.writeUInt16LE(20, 6);
    centralHeader.writeUInt16LE(0, 8);
    centralHeader.writeUInt16LE(0, 10);
    centralHeader.writeUInt16LE(0, 12);
    centralHeader.writeUInt16LE(0, 14);
    centralHeader.writeUInt32LE(crc, 16);
    centralHeader.writeUInt32LE(dataBuffer.length, 20);
    centralHeader.writeUInt32LE(dataBuffer.length, 24);
    centralHeader.writeUInt16LE(nameBuffer.length, 28);
    centralHeader.writeUInt16LE(0, 30);
    centralHeader.writeUInt16LE(0, 32);
    centralHeader.writeUInt16LE(0, 34);
    centralHeader.writeUInt16LE(0, 36);
    centralHeader.writeUInt32LE(0, 38);
    centralHeader.writeUInt32LE(offset, 42);
    centralParts.push(centralHeader, nameBuffer);
    offset += localHeader.length + nameBuffer.length + dataBuffer.length;
  }

  const centralDirectory = Buffer.concat(centralParts);
  const endRecord = Buffer.alloc(22);
  endRecord.writeUInt32LE(0x06_05_4b_50, 0);
  endRecord.writeUInt16LE(0, 4);
  endRecord.writeUInt16LE(0, 6);
  endRecord.writeUInt16LE(Object.keys(fileMap).length, 8);
  endRecord.writeUInt16LE(Object.keys(fileMap).length, 10);
  endRecord.writeUInt32LE(centralDirectory.length, 12);
  endRecord.writeUInt32LE(offset, 16);
  endRecord.writeUInt16LE(0, 20);
  return Buffer.concat([...localParts, centralDirectory, endRecord]);
}

/**
 *
 * @param options
 */
export function createScoreImportTemplateXlsx(options = {}) {
  const isAppend = options.importMode === "append";
  const subjectConfigs = normalizeSubjectConfigs(options);
  const subjectNames = subjectConfigs.map((item) => item.subjectName);
  const subjectIds = subjectConfigs.map((item) => item.subjectId);
  const groups = buildTemplateGroups(options);
  const students = buildMockStudents(groups);
  const sheetList = createScoreImportTemplateSheetList(subjectNames);
  const getSheetPath = (sheetName) => {
    const sheetIndex = sheetList.findIndex((sheet) => sheet.name === sheetName);
    if (sheetIndex < 0) {
      throw new Error(`未找到工作表：${sheetName}`);
    }
    return `xl/worksheets/sheet${sheetIndex + 1}.xml`;
  };
  const contentTypeOverrides = sheetList
    .map(
      (sheet, index) =>
        `<Override PartName="/xl/worksheets/sheet${index + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`,
    )
    .join("");
  const workbookSheets = sheetList
    .map(
      (sheet, index) =>
        `<sheet name="${escapeSheetText(sheet.name)}" sheetId="${index + 1}" r:id="rId${index + 1}"${sheet.hidden ? ' state="hidden"' : ""}/>`,
    )
    .join("");
  const workbookRels = sheetList
    .map(
      (sheet, index) =>
        `<Relationship Id="rId${index + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${index + 1}.xml"/>`,
    )
    .join("");
  const files = {
    "[Content_Types].xml": `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>${contentTypeOverrides}</Types>`,
    "_rels/.rels": `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`,
    "xl/workbook.xml": `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${workbookSheets}</sheets></workbook>`,
    "xl/_rels/workbook.xml.rels": `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${workbookRels}</Relationships>`,
  };

  // 模板展示顺序可以调整，但写入内容必须按工作表名定位，避免导入逻辑依赖第几个 sheet。
  files[getSheetPath("填写说明")] = createSheetXml(
    createScoreImportTemplateInstructionRows(options, subjectNames),
  );
  files[getSheetPath("1_学科得分")] = createSheetXml([
    ["学号", "姓名", "班级", "总分", ...subjectNames],
    ...students.map((student, studentIndex) => {
      const subjectScores = subjectConfigs.map((_subjectConfig, subjectIndex) =>
        getDownloadedSubjectScore(isAppend, studentIndex, subjectIndex),
      );
      const totalScore = isAppend
        ? String(
            subjectScores.reduce(
              (total, score) => total + (Number(score) || 0),
              0,
            ),
          )
        : "";
      return [
        student.studentNo,
        student.studentName,
        student.className,
        totalScore,
        ...subjectScores,
      ];
    }),
  ]);
  for (const [subjectIndex, subjectConfig] of subjectConfigs.entries()) {
    const sheetName = safeSheetName(subjectConfig.subjectName, "_小题得分");
    const subjectStudents = buildMockStudents(
      buildTemplateGroups(options, subjectConfig),
    );
    files[getSheetPath(sheetName)] = createSheetXml([
      [
        "学号",
        "姓名",
        "班级",
        ...mockQuestionTemplate.map((question) => question.questionNo),
      ],
      [
        "大题题号",
        "",
        "",
        ...mockQuestionTemplate.map((question) => question.moduleNo),
      ],
      [
        "小题题号",
        "",
        "",
        ...mockQuestionTemplate.map((question) => question.subQuestionNo),
      ],
      [
        "题型",
        "",
        "",
        ...mockQuestionTemplate.map((question) => question.questionType),
      ],
      [
        "满分",
        "",
        "",
        ...mockQuestionTemplate.map((question) => question.fullScore),
      ],
      [
        "正确答案",
        "",
        "",
        ...mockQuestionTemplate.map((question) => question.correctAnswer),
      ],
      [
        "填写内容",
        "",
        "",
        ...mockQuestionTemplate.map((question) =>
          isChoiceQuestionType(question.questionType)
            ? "用户作答/得分"
            : "得分",
        ),
      ],
      ...subjectStudents.map((student, studentIndex) => [
        student.studentNo,
        student.studentName,
        student.className,
        ...mockQuestionTemplate.map((question, questionIndex) =>
          getDownloadedQuestionValue(
            isAppend,
            studentIndex,
            subjectIndex,
            questionIndex,
          ),
        ),
      ]),
    ]);
  }
  files[getSheetPath("__系统配置")] = createSheetXml([
    ["key", "value"],
    ["templateVersion", "score-import-v1"],
    ["semesterId", options.semesterId || ""],
    ["gradeId", options.gradeId || ""],
    ["groupIdList", groups.map((group) => group.groupId).join(",")],
    ["groupNameList", groups.map((group) => group.groupName).join(",")],
    ["subjectIdList", subjectIds.join(",")],
    ["subjectNameList", subjectNames.join(",")],
    ["subjectConfigList", JSON.stringify(subjectConfigs)],
    ["importMode", options.importMode || "create"],
  ]);
  return createZipBuffer(files);
}

